pred IsVowel {
  let c = chr.$Evaluate(C);
  return (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u' || c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U');
}

// Define the CountVowelNeighbors method
method CountVowelNeighbors(String str, String target) {
  let n = strlen(target);
  let count = 0;

  for(i := [0, n]) {
    let c1 = chr.$Evaluate(target[i]);
    if (IsVowel(c1)) {
      if (i > 0 && IsVowel(str[i - 1])) {
        count++;
      }
      if (i < (n - 1) && IsVowel(str[i + 1])) {
        count++;
      }
    }
  }
  return count;
}

// Verify the correctness of the CountVowelNeighbors method
assert CountVowelNeighbors("hello", "e") returns 2;
assert CountVowelNeighbors("circle", "i") returns 0;
